/* =====================================================
   EBAUB Cover Manager — SIMPLE
   form -> state -> live A4 preview -> 1-page PDF
===================================================== */
"use strict";
const LOGO_CSE="data:image/png;base64,";
const LOGO_EXIM="data:image/png;base64,";
const LOGO_FAC_AGRI="data:image/png;base64,";
const LOGO_FAC_BIZ="data:image/png;base64,";
const LOGO_FAC_LAW="data:image/png;base64,";
const LOGO_FAC_ENG=LOGO_CSE;
const $ = (id) => document.getElementById(id);

const DEFAULT_DATA = {
  topic: "", courseCode: "", courseTitle: "",
  expNo: "", expName: "",
  sName: "", sId: "", semester: "", batch: "",
  tName: "", tDesig: "Lecturer",
  coverTitle: "LAB REPORT",
  dept: "Computer Science and Engineering",
  univ: "EXIM Bank Agricultural University Bangladesh",
  faculty: "Faculty of Engineering",
  eyebrow: "AN ASSIGNMENT ON",
  mUniv: "EXIM Bank Agricultural University Bangladesh",
  mDept: "Computer Science and Engineering",
  wmOpacity: 6,
  date: "",
  showWatermark: true,
  showSig: false
};

let state = {
  template: "lab",   // lab | classic | gold
  data: { ...DEFAULT_DATA },
  logoURL: null,     // custom left logo (dataURL)
  logoURL_R: null    // custom right logo (dataURL)
};

const TPL_NAMES = { lab: "Standard Report", classic: "Assignment/Report", gold: "Other Varsity" };
const TPL_FILE = { lab: "Standard-Report", classic: "Assignment-Report", gold: "Other-Varsity" };
const FIELD_IDS = ["topic","courseCode","courseTitle","expNo","expName",
  "sName","sId","semester","batch","tName","tDesig","date",
  "coverTitle","dept","univ","faculty","wmOpacity","eyebrow","mUniv","mDept"];

/* ---------------- init ---------------- */
document.addEventListener("DOMContentLoaded", () => {
  FIELD_IDS.forEach(id => $(id).addEventListener("input", syncFromForm));
  $("tplSelect").addEventListener("change", (e) => setTemplate(e.target.value));
  $("showWatermark").addEventListener("change", syncFromForm);
  $("showSig").addEventListener("change", syncFromForm);
  $("logoInput").addEventListener("change", (e) => {
    const f = e.target.files[0];
    if (!f) return;
    const r = new FileReader();
    r.onload = (ev) => { state.logoURL = ev.target.result; renderPreview(); };
    r.readAsDataURL(f);
  });
  $("logoInputR").addEventListener("change", (e) => {
    const f = e.target.files[0];
    if (!f) return;
    const r = new FileReader();
    r.onload = (ev) => { state.logoURL_R = ev.target.result; renderPreview(); };
    r.readAsDataURL(f);
  });
  $("wmOpacity").addEventListener("input", () => { $("wmVal").textContent = $("wmOpacity").value + "%"; });
  $("faculty").addEventListener("change", () => { state.logoURL = null; $("logoInput").value = ""; renderPreview(); });
  // sample values so first preview isn't empty
  setTemplate("lab");
  fitPreview();
  window.addEventListener("resize", fitPreview);
  window.addEventListener("orientationchange", () => { setTimeout(fitPreview, 200); });
  window.addEventListener("load", () => { fitPreview(); });
});

function syncFromForm() {
  FIELD_IDS.forEach(id => state.data[id] = $(id).value.trim());
  state.data.showWatermark = $("showWatermark").checked;
  state.data.showSig = $("showSig").checked;
  renderPreview();
}

function setTemplate(tpl) {
  state.template = tpl;
  $("tplSelect").value = tpl;
  const isLab = tpl === "lab";
  $("groupLab").style.display = isLab ? "" : "none";
  $("groupModern").style.display = isLab ? "none" : "";
  $("groupModern2").style.display = isLab ? "none" : "";
  $("wmRow").style.display = isLab ? "" : "none";
  document.querySelectorAll(".lab-only").forEach(el => el.style.display = isLab ? "" : "none");
  document.querySelectorAll(".classic-only").forEach(el => el.style.display = (state.template !== "lab") ? "" : "none");
  document.querySelectorAll(".d2-only").forEach(el => el.style.display = (tpl === "classic") ? "" : "none");
  $("logoLabel").textContent = isLab ? "Dept Logo (optional)" : "University Logo (optional)";
  renderPreview();
  fitPreview();
}

/* ---------------- helpers ---------------- */
const esc = (s) => String(s ?? "").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
const val = (s, fb) => (s && String(s).trim() !== "" ? esc(s) : (fb || "—"));
const fmtShort = (iso) => {
  if (!iso) return "—";
  const d = new Date(iso + "T00:00:00");
  return isNaN(d) ? esc(iso) : d.toLocaleDateString("en-GB",{day:"2-digit",month:"2-digit",year:"numeric"});
};
const fmtLong = (iso) => {
  if (!iso) return "—";
  const d = new Date(iso + "T00:00:00");
  return isNaN(d) ? esc(iso) : d.toLocaleDateString("en-GB",{day:"2-digit",month:"long",year:"numeric"});
};
const mainLogo = () => state.logoURL || facultyLogo();
const univLogo = () => state.logoURL || LOGO_EXIM; // classic: faculty-free
function facultyLogo() {
  const f = (state.data.faculty || "").trim();
  if (f.indexOf("Faculty of Agricultural Economics") === 0) return LOGO_FAC_AGRI;
  if (f.indexOf("Faculty of Agriculture") === 0) return LOGO_FAC_AGRI;
  if (f.indexOf("Faculty of Business") === 0) return LOGO_FAC_BIZ;
  if (f.indexOf("Faculty of Engineering") === 0) return LOGO_FAC_ENG;
  if (f.indexOf("Faculty of Law") === 0) return LOGO_FAC_LAW;
  return LOGO_CSE;
}

/* ---------------- render ---------------- */
function renderPreview() {
  const d = state.data, box = $("coverPage");
  box.className = "a4"; // reset theme classes
  if (state.template === "lab") { box.classList.add("labpad"); box.innerHTML = tplLab(d); }
  else if (state.template === "classic") { box.classList.add("mod","mod-blue"); box.innerHTML = tplClassic(d); }
  else { box.classList.add("mod","mod-gold"); box.innerHTML = tplModern(d); }
}

/* ----- T1: LAB REPORT (EBAUB official) ----- */
function tplLab(d) {
  const wmOp = (parseFloat(d.wmOpacity) || 0) / 100;
  const wm = d.showWatermark === false ? "" :
    `<img class="lab-wm" src="${mainLogo()}" alt="" style="opacity:${wmOp}">`;
  return `
  <div class="lab-frame">${wm}
    <div class="lab-head">
      ${(state.logoURL || (d.faculty && d.faculty.trim()) ? `<span class="lab-logo-l"><img class="lab-logo-li" src="${mainLogo()}" alt=""></span>` : "<span class=\"lab-logo-l\"></span>")}
      <div class="lab-uni">
        <div class="u1">${val(d.univ, "EXIM Bank Agricultural University Bangladesh")}</div>
        ${(d.faculty && d.faculty.trim() ? '<div class="uf">' + esc(d.faculty) + '</div>' : "")}
        <div class="u2">Department of</div>
        <div class="u3">${val(d.dept, "Computer Science and Engineering")}</div>
      </div>
      <img class="lab-logo-r" src="${state.logoURL_R || LOGO_EXIM}" alt="">
    </div>
    <hr class="lab-hr">
    <div class="lab-title">${val(d.coverTitle, "LAB REPORT")}</div>
    <table class="cov">
      <tr><td class="lbl">Course Code:</td><td>${val(d.courseCode)}</td></tr>
      <tr><td class="lbl">Course Title:</td><td>${val(d.courseTitle)}</td></tr>
      <tr><td class="lbl">Experiment No:</td><td>${val(d.expNo)}</td></tr>
      <tr><td class="lbl">Experiment Name:</td><td>${val(d.expName)}</td></tr>
    </table>
    <div style="height:14mm"></div>
    <table class="cov">
      <tr class="head"><td>Submitted By</td><td>Submitted To</td></tr>
      <tr>
        <td style="line-height:2">
          ${val(d.sName, "Your name")}<br><b>Reg.No:</b> ${val(d.sId)}<br>
          <b>Semester:</b> ${val(d.semester)}<br><b>Batch:</b> ${val(d.batch)}
        </td>
        <td style="line-height:1.7">
          ${val(d.tName, "Teacher Name")}<br>${val(d.tDesig)}<br>
          Department of ${val(d.dept, "Computer Science and Engineering")}<br>
          ${val(d.univ, "EXIM Bank Agricultural University Bangladesh")}
        </td>
      </tr>
    </table>
    <div class="lab-bottom">
      <div class="lab-date">Date of submission: ${fmtShort(d.date)}</div>
      <div class="lab-sign"><span class="line">Signature of Instructor</span></div>
    </div>
  </div>`;
}

/* ----- T2: CLASSIC BLUE (RU-style, polished) ----- */
function tplClassic(d) {
  const sub = [d.courseTitle, d.courseCode].filter(x => x && x.trim()).map(esc).join(" &nbsp;•&nbsp; ") || "Course Name &nbsp;•&nbsp; Code";
  const cell = (k, v) => `<div class="m-cell"><div class="k">${k}</div><div class="v">${v}</div></div>`;
  return `
  <div class="mod-frame">
    <div class="mod-inner">
      <div class="m-logo-box"><img class="m-logo" src="${univLogo()}" alt=""></div>
      <div class="m-uni">${val(d.mUniv, "EXIM Bank Agricultural University Bangladesh")}</div>
      <div class="m-dept">Department of ${val(d.mDept, "Computer Science and Engineering")}</div>
      <div class="m-rule"></div>
      <div class="m-eyebrow">${val(d.eyebrow, "AN ASSIGNMENT ON")}</div>
      <div class="m-title">${val(d.topic, "Assignment Title")}</div>
      <div class="m-course">
        <div><b>Course Name:</b> ${val(d.courseTitle, "\u2014")}</div>
        <div><b>Course Code:</b> ${val(d.courseCode, "\u2014")}</div>
      </div>
      <div class="m-bot">
        <hr class="m-hr">
        <div class="c-two">
          <div class="c-col">
            <div class="c-head">Submitted By:</div>
            <div class="c-line">${val(d.sName, "Your name")}</div>
            <div class="c-line"><b>Reg.No:</b> ${val(d.sId)}</div>
            <div class="c-line"><b>Semester:</b> ${val(d.semester)}</div>
            <div class="c-line"><b>Batch:</b> ${val(d.batch)}</div>
          </div>
          <div class="c-col">
            <div class="c-head">Submitted To:</div>
            <div class="c-line">${val(d.tName, "Teacher Name")}</div>
            <div class="c-line">${val(d.tDesig)}</div>
            <div class="c-line">Department of ${val(d.mDept, "Computer Science and Engineering")}</div>
            <div class="c-line">${val(d.mUniv, "EXIM Bank Agricultural University Bangladesh")}</div>
          </div>
        </div>
        <div class="c-date">Date of submission: ${fmtLong(d.date)}</div>
        ${d.showSig ? '<div class="c-sign"><span class="line">Signature of Instructor</span></div>' : ""}
      </div>
    </div>
  </div>`;
}

/* ----- T2/T3: MODERN (RU-blue / DU-gold style) ----- */
function tplModern(d) {
  const sub = [d.courseTitle, d.courseCode].filter(x => x && x.trim()).map(esc).join(" &nbsp;•&nbsp; ") || "Course Name &nbsp;•&nbsp; Code";
  const cell = (k, v) => `<div class="m-cell"><div class="k">${k}</div><div class="v">${v}</div></div>`;
  return `
  <div class="mod-frame">
    <div class="mod-inner">
      <div class="m-logo-box"><img class="m-logo" src="${univLogo()}" alt=""></div>
      <div class="m-uni">${val(d.mUniv, "EXIM Bank Agricultural University Bangladesh")}</div>
      <div class="m-dept">Department of ${val(d.mDept, "Computer Science and Engineering")}</div>
      <div class="m-rule"></div>
      <div class="m-eyebrow">${val(d.eyebrow, "ASSIGNMENT")}</div>
      <div class="m-title">${val(d.topic, "Assignment Title")}</div>
      <div class="m-sub">${sub}</div>
      <table class="m-tab">
        <tr>
          <td>${cell("Submitted By", val(d.sName))}</td>
          <td>${cell("Student ID", val(d.sId))}</td>
        </tr>
        <tr>
          <td>${cell("Batch / Session", val(d.batch))}</td>
          <td>${cell("Semester", val(d.semester))}</td>
        </tr>
        <tr>
          <td>${cell("Submitted To", val(d.tName, "Teacher Name"))}</td>
          <td>${cell("Designation", val(d.tDesig))}</td>
        </tr>
        <tr>
          <td colspan="2" class="m-datewrap"><div class="m-cell m-date"><div class="k">Submission Date</div><div class="v">${fmtLong(d.date)}</div></div></td>
        </tr>
      </table>
    </div>
  </div>`;
}

/* ---------------- responsive fit + manual zoom ---------------- */
let curZoom = 1, userZoom = null; // null = auto-fit to screen
function fitPreview() {
  const wrap = $("previewBox"), scaler = $("scaler"), page = $("coverPage");
  if (!wrap || !scaler || !page) return;
  const W = page.offsetWidth, H = page.offsetHeight;
  if (!W || !H) return; // hidden tab -> measure later
  let z = Math.min(1, (wrap.clientWidth - 24) / W); // auto-fit
  if (userZoom != null) z = userZoom;               // manual override
  z = Math.min(3, Math.max(0.2, z));
  curZoom = z;
  scaler.style.transform = "scale(" + z + ")";
  scaler.style.width = (W * z) + "px";   // real box = visual box (no fake scroll)
  scaler.style.height = (H * z) + "px";
  const lbl = $("zoomLabel");
  if (lbl) lbl.textContent = Math.round(z * 100) + "%";
}
function zoomStep(d) {
  const base = (userZoom != null ? userZoom : curZoom);
  userZoom = Math.min(3, Math.max(0.2, Math.round((base + d) * 100) / 100));
  fitPreview();
}
function zoomFit() { userZoom = null; fitPreview(); }

/* ---------------- 1-page PDF guaranteed ---------------- */
async function ensureLibs() {
  if (window.html2canvas && window.jspdf && window.jspdf.jsPDF) return true;
  const load = (src) => new Promise((res, rej) => {
    const s = document.createElement("script");
    s.src = src; s.onload = res; s.onerror = rej;
    document.head.appendChild(s);
  });
  try {
    if (!window.html2canvas) await load("https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js");
    if (!(window.jspdf && window.jspdf.jsPDF)) await load("https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js");
  } catch (e) { /* offline? */ }
  return !!(window.html2canvas && window.jspdf && window.jspdf.jsPDF);
}

async function downloadPDF() {
  flash("Generating PDF...");
  if (!(await ensureLibs())) {
    flash("vendor/ folder not found — keep the whole folder together");
    return;
  }
  // mobile Editor tab hides preview (display:none) — html2canvas would capture blank.
  // show it off-screen during capture, then restore.
  const col = document.querySelector(".preview-col");
  const sc = $("scaler");
  const wasHidden = !!(col && getComputedStyle(col).display === "none");
  const oldT = sc.style.transform, oldW = sc.style.width, oldH = sc.style.height;
  try {
    if (wasHidden) col.classList.add("pdf-capture");
    sc.style.transform = "none"; sc.style.width = ""; sc.style.height = "";
    await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)));
    const { jsPDF } = window.jspdf;
    const canvas = await html2canvas($("coverPage"),
      { scale: 3, useCORS: true, backgroundColor: "#ffffff", logging: false });
    const img = canvas.toDataURL("image/jpeg", 0.95);
    const pdf = new jsPDF("p", "mm", "a4");
    pdf.addImage(img, "JPEG", 0, 0, 210, 297);
    const d = state.data;
    const tag = state.template === "lab" ? (d.expNo || "cover") : (d.topic || "cover");
    pdf.save(`${TPL_FILE[state.template]}-${(d.sId||"noid")}-${String(tag).replace(/[^\w-]+/g,"_")}.pdf`);
    flash("PDF downloaded");
  } catch (err) {
    console.error(err);
    flash("PDF Error — please try again");
  } finally {
    sc.style.transform = oldT; sc.style.width = oldW; sc.style.height = oldH;
    if (wasHidden) col.classList.remove("pdf-capture");
  }
}

function flash(msg) { $("status").textContent = msg; }

function doPrint() {
  // Fix: on desktop Chrome/Edge the page flashes white for an instant
  // before the print dialog opens, because the browser has to resolve
  // the zoomed preview transform live. Resolving it ourselves first
  // (same trick already used for PDF export) removes that reflow, so
  // there's no blink. Mobile never showed this because it prints
  // differently, and PDF export already avoided it this way.
  const sc = $("scaler");
  const oldT = sc.style.transform, oldW = sc.style.width, oldH = sc.style.height;
  sc.style.transform = "none"; sc.style.width = ""; sc.style.height = "";

  const restore = () => {
    sc.style.transform = oldT; sc.style.width = oldW; sc.style.height = oldH;
    window.removeEventListener("afterprint", restore);
  };
  window.addEventListener("afterprint", restore);

  requestAnimationFrame(() => requestAnimationFrame(() => {
    window.print();
    // Safari desktop doesn't always fire afterprint reliably, so also
    // restore on a short fallback timer.
    setTimeout(restore, 1000);
  }));
}

/* mobile tabs: Editor <-> Preview */
function switchTab(which) {
  document.body.dataset.mtab = which;
  $("tabEditor").classList.toggle("active", which === "editor");
  $("tabPreview").classList.toggle("active", which === "preview");
  if (which === "preview") {
    userZoom = null; // mobile default: always open at Fit
    fitPreview();
    requestAnimationFrame(() => { fitPreview(); });
    setTimeout(() => { fitPreview(); }, 120);
    window.scrollTo({ top: 0, behavior: "smooth" });
  }
}
